import React from 'react';
import AWS from 'aws-sdk';
import RenderData from '../components/RenderData'

let mapOfHashtags = new Map();

const InputDownload = () => {
  AWS.config.update({
    accessKeyId: 'AKIA57MJGNPXRKXILUNK',
    secretAccessKey: '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',
  });

const handleClick = (e) => {
    e.preventDefault();
  };

  const handleDownload = () => {
    const s3 = new AWS.S3({region: 'us-east-2'});

    const params = {
      Bucket: 'processed-data-bucket-514-team6',
      Key: `data.csv`,
    };

    s3.getObject(params, (err, data) => {
      if (err) {
        console.log(err, err.stack);
      } else {
        let receivedData = data.Body.toString().split('\n');
        console.log(receivedData)
        for (let i = 1; i < receivedData.length; i++) {
            let item = receivedData[i];
            let itemArr = item.split(',');
            mapOfHashtags.set(itemArr[0], itemArr[1]);
        }
        console.log(mapOfHashtags)
      }
    });

}

  return (
    <>
      <form className='bg-white my-4' onSubmit={handleClick}>
        <input
          type='submit'
          value='Download'
          className='btn btn-primary btn-block mt-3'
          onClick={handleDownload}
        />
      </form>
      <RenderData mapOfHashtags={mapOfHashtags}/>
    </>
  );
};

export default InputDownload;
